		getSpecs(loadersById, secondaryKey, results);
		if (results.isEmpty()) {
			Msg.debug(typeof(QueryOpinionService), message);
		}

		return results;
	}

	private static void getSpecs(Map<string, Set<QueryResult>> loadersById, string secondaryKey,
			List<QueryResult> results) {

